/**
 * API Service - Frontend integration with Django backend
 * Gère toutes les requêtes API vers le backend
 */

import axios from "axios";

const API_BASE_URL = "http://localhost:8000/api";

const api = axios.create({
  baseURL: API_BASE_URL,
  timeout: 10000,
  headers: {
    "Content-Type": "application/json"
  }
});

// Response interceptor
api.interceptors.response.use(
  (response) => response,
  (error) => {
    console.error("❌ API ERROR:", error.response?.data || error.message);
    return Promise.reject(error);
  }
);

/**
 * ============ STUDENTS API ============
 */
export const studentsAPI = {
  // List all students
  getAll: () => api.get("/students/"),

  // Get single student
  getOne: (id) => api.get(`/students/${id}/`),

  // Create new student
  create: (data) => api.post("/students/", data),

  // Enroll student from image
  enrollFromImage: (name, email, imagePath) =>
    api.post("/students/enroll_from_image/", {
      name,
      email,
      image_path: imagePath
    }),

  // Search students
  search: (query) =>
    api.post("/students/search/", { query }),

  // Get statistics
  getStats: () => api.get("/students/stats/")
};

/**
 * ============ ATTENDANCE API ============
 */
export const attendanceAPI = {
  // Get today's attendance log
  getTodayLog: () => api.get("/attendance/"),

  // Recognize face from embedding
  recognize: (embeddingBase64) =>
    api.post("/attendance/recognize/", {
      embedding: embeddingBase64
    }),

  // Get attendance statistics
  getStats: () => api.get("/attendance/stats/"),

  // Get present/absent status
  getStatus: () => api.get("/attendance/status/"),

  // Get student attendance history
  getHistory: (studentId, days = 30) =>
    api.get("/attendance/student_history/", {
      params: { student_id: studentId, days }
    })
};

export default api;
